import React, { useState, useEffect } from 'react';
import { graphql } from 'gatsby';
import PropTypes from 'prop-types';
import { Layout, Hero, About, Jobs, Education, Skills, Featured, Contact } from '@components';
import styled from 'styled-components';
import { Main } from '@styles';
import { defaultProfile } from '@config';
import sdeSkillOrder from '../../content/skills/sde/skillOrder.json';
import roboSkillOrder from '../../content/skills/robo/skillOrder.json';
import sdeProjectOrder from '../../content/featured/sde/projectOrder.json';
import roboProjectOrder from '../../content/featured/robo/projectOrder.json';

const StyledMainContainer = styled(Main)`
  counter-reset: section;
`;

const IndexPage = ({ location, data }) => {
  const [profile, setProfile] = useState(location.pathname.replaceAll("/", "") || defaultProfile);

  useEffect(() => {
    // This will set the profile whenever the pathname changes
    const updatedProfile = location.pathname.replaceAll("/", "") || defaultProfile;
    setProfile(updatedProfile);
  }, [location.pathname]); // Dependency on pathname to re-run effect

  // Conditional rendering of data based on profile state
  const renderDataByProfile = (profile) => {
    const commonData = {
      jobs: data.jobs.edges,
      education: data.education.edges,
      skills: data.skills.edges,
      contact: data.contact.edges,
    };

    switch (profile) {
      case 'robo':
        return {
          ...commonData,
          hero: data.roboHero.edges,
          about: data.roboAbout.edges,
          featured: data.roboFeatured.edges,
          projects: data.roboProjects.edges,
          skillorder: roboSkillOrder,
          projectorder: roboProjectOrder,
          certifications: data.roboCertifications.edges,
        };
      case 'sde':
      default:
        return {
          ...commonData,
          hero: data.sdeHero.edges,
          about: data.sdeAbout.edges,
          featured: data.sdeFeatured.edges,
          projects: data.sdeProjects.edges,
          skillorder: sdeSkillOrder,
          projectorder: sdeProjectOrder,
          certifications: data.sdeCertifications.edges,
        };
    }
  };

  const profileData = renderDataByProfile(profile);

  return (
    <Layout location={location}>
      <StyledMainContainer className="fillHeight">
        <Hero data={profileData.hero} />
        <About data={profileData.about} />
        <Jobs data={profileData.jobs} />
        <Education data={profileData.education} />
        <Featured data={profileData.featured} projectOrder={profileData.projectorder} />
        {/* <Projects data={profileData.projects} /> */}
        <Skills skillsData={profileData.skills} skillOrder={profileData.skillorder} />
        {/* <Certifications data={profileData.certifications} /> */}
        <Contact data={profileData.contact} />
      </StyledMainContainer>
    </Layout>
  );
};

IndexPage.propTypes = {
  location: PropTypes.object.isRequired,
  data: PropTypes.object.isRequired,
};

export default IndexPage;

